var transactions_table;
$(document).ready(function() {
    var accountTransactionUrl = $('#transactionFilterForm').attr('action');
    transactions_table = $('#transactions_table').DataTable( {
        pageLength: 25,
        processing: true,
        serverSide: true,
        searching: false,
        lengthChange: false,
        ajax: {
            url: accountTransactionUrl,
            type: "POST",
            dataType: "json",
            contentType: "application/json",
            data: function ( d ) {
                var filterMap = $("#transactionFilterForm").serializeFormJSON();
                d.filterMap=filterMap;
                return JSON.stringify(d);
            }
        },
        columns: [
            { data: 'transactiontime' },
            { data: 'credit' },
            { data: 'ordernumber' },
            { data: 'paymentid' },
            { data: 'note' }
        ],
        columnDefs: [
            {
                "render": function (data, type, row ) {
                    var date = new Date(data);
                    return date.toLocaleString();
                },
                "targets": 0
            }
        ],
        'sDom': 'lTfr<"clearfix">tip',
        'oTableTools': {
            'aButtons': [

            ]
        }
    } );

    $('#transactionFilter').on('click', function(){
        transactions_table.ajax.reload();
    });

    $('.btn-buy-credit').on('click',function(){
        $('#transactionModal').modal('show');
    });

    $('.btn-buy-credit-submit').on('click',function(){
        $('#buyCreditForm').submit();
    });
    $('.bd-sidebar').find('.bd-sidebar-account-balance').addClass('active');
});
